package com.servicerca;import com.servicerca.mapper.ApiMapper;import com.servicerca.model.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;class ApiMapperTest{@Test void neverExposesEncryptedDni(){var user=User.builder().id(UUID.randomUUID()).email("test@demo.com").dniEncrypted("secret-ciphertext").trades(new HashSet<>()).build();var response=new ApiMapper().toUserResponse(user);assertThat(response.maskedDni()).doesNotContain("secret-ciphertext");}}
